import React from "react";
import { Card, Col, Row } from "react-bootstrap";
import { Link } from "react-router-dom";

function AdminDashboard() {
  return (
    <>
      <h1 className="mb-4">Admin Dashboard</h1>
      <Row className="g-3">
        <Col md={6}>
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Manage Movies</Card.Title>
              <Card.Text>Add, edit, and remove movies.</Card.Text>
              <Link to="/admin/movies">Go to Movies</Link>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6}>
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Manage Shows</Card.Title>
              <Card.Text>Create and update show timings.</Card.Text>
              <Link to="/admin/shows">Go to Shows</Link>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </>
  );
}

export default AdminDashboard;
