import React from "react";
import { Alert, Card } from "react-bootstrap";
import { Link, useLocation } from "react-router-dom";

function BookingConfirmationPage() {
  const { state } = useLocation();

  return (
    <Card>
      <Card.Body>
        <h2 className="mb-3">Booking Confirmed</h2>
        <Alert variant="success">Your booking has been confirmed successfully.</Alert>
        <p>
          Booking ID: <strong>{state?.bookingId || "N/A"}</strong>
        </p>
        <p>
          Seats: <strong>{state?.seats?.join(", ") || "N/A"}</strong>
        </p>
        <Link to="/booking-history">View Booking History</Link>
      </Card.Body>
    </Card>
  );
}

export default BookingConfirmationPage;
