import React, { useEffect, useState } from "react";
import { Button, Card, Form, Table } from "react-bootstrap";
import axiosInstance from "../../api/axios";

function AdminMovies() {
  const [movies, setMovies] = useState([]);
  const [title, setTitle] = useState("");

  const fetchMovies = async () => {
    const { data } = await axiosInstance.get("/movies");
    setMovies(Array.isArray(data) ? data : data.movies || []);
  };

  useEffect(() => {
    fetchMovies().catch(() => setMovies([]));
  }, []);

  const handleAddMovie = async (event) => {
    event.preventDefault();
    if (!title.trim()) {
      return;
    }
    await axiosInstance.post("/movies", { title });
    setTitle("");
    fetchMovies();
  };

  return (
    <Card>
      <Card.Body>
        <h2 className="mb-3">Admin Movies</h2>
        <Form className="d-flex gap-2 mb-4" onSubmit={handleAddMovie}>
          <Form.Control
            placeholder="New movie title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <Button type="submit">Add</Button>
        </Form>

        <Table striped responsive>
          <thead>
            <tr>
              <th>Title</th>
            </tr>
          </thead>
          <tbody>
            {movies.map((movie) => (
              <tr key={movie.id || movie._id}>
                <td>{movie.title}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      </Card.Body>
    </Card>
  );
}

export default AdminMovies;
