import React, { useEffect, useState } from "react";
import { Button, Card, Form, Table } from "react-bootstrap";
import axiosInstance from "../../api/axios";
import { formatDate } from "../../utils/helpers";

function AdminShows() {
  const [shows, setShows] = useState([]);
  const [movieId, setMovieId] = useState("");
  const [showTime, setShowTime] = useState("");

  const fetchShows = async () => {
    const { data } = await axiosInstance.get("/shows");
    setShows(Array.isArray(data) ? data : data.shows || []);
  };

  useEffect(() => {
    fetchShows().catch(() => setShows([]));
  }, []);

  const handleAddShow = async (event) => {
    event.preventDefault();
    if (!movieId.trim() || !showTime) {
      return;
    }
    await axiosInstance.post("/shows", { movieId, showTime });
    setMovieId("");
    setShowTime("");
    fetchShows();
  };

  return (
    <Card>
      <Card.Body>
        <h2 className="mb-3">Admin Shows</h2>
        <Form className="row g-2 mb-4" onSubmit={handleAddShow}>
          <div className="col-md-4">
            <Form.Control
              placeholder="Movie ID"
              value={movieId}
              onChange={(e) => setMovieId(e.target.value)}
            />
          </div>
          <div className="col-md-4">
            <Form.Control
              type="datetime-local"
              value={showTime}
              onChange={(e) => setShowTime(e.target.value)}
            />
          </div>
          <div className="col-md-4 d-grid">
            <Button type="submit">Add Show</Button>
          </div>
        </Form>

        <Table striped responsive>
          <thead>
            <tr>
              <th>ID</th>
              <th>Movie</th>
              <th>Show Time</th>
            </tr>
          </thead>
          <tbody>
            {shows.map((show) => (
              <tr key={show.id || show._id}>
                <td>{show.id || show._id}</td>
                <td>{show.movieId || show.movie?.title || "N/A"}</td>
                <td>{formatDate(show.showTime)}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      </Card.Body>
    </Card>
  );
}

export default AdminShows;
