import React, { useMemo, useState } from "react";
import { Button, Card } from "react-bootstrap";
import { useNavigate, useParams } from "react-router-dom";
import { generateSeatLayout } from "../utils/helpers";

function SeatSelectionPage() {
  const { showId } = useParams();
  const navigate = useNavigate();
  const [selectedSeats, setSelectedSeats] = useState([]);
  const seats = useMemo(() => generateSeatLayout(6, 8), []);

  const toggleSeat = (seatId) => {
    setSelectedSeats((previous) =>
      previous.includes(seatId)
        ? previous.filter((seat) => seat !== seatId)
        : [...previous, seatId]
    );
  };

  const proceedToPayment = () => {
    navigate("/payment", {
      state: {
        showId,
        selectedSeats,
        amount: selectedSeats.length * 200
      }
    });
  };

  return (
    <Card>
      <Card.Body>
        <h2 className="mb-3">Select Seats</h2>
        <div className="seat-grid mb-3">
          {seats.map((seatId) => {
            const active = selectedSeats.includes(seatId);
            return (
              <button
                key={seatId}
                type="button"
                className={`seat-btn ${active ? "active" : ""}`}
                onClick={() => toggleSeat(seatId)}
              >
                {seatId}
              </button>
            );
          })}
        </div>
        <p className="mb-3">Selected: {selectedSeats.join(", ") || "None"}</p>
        <Button disabled={!selectedSeats.length} onClick={proceedToPayment}>
          Proceed to Payment
        </Button>
      </Card.Body>
    </Card>
  );
}

export default SeatSelectionPage;
