import React, { useEffect, useState } from "react";
import { Col, Row } from "react-bootstrap";
import axiosInstance from "../api/axios";
import LoadingSpinner from "../components/LoadingSpinner";
import MovieCard from "../components/MovieCard";

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchMovies() {
      try {
        const { data } = await axiosInstance.get("/movies");
        setMovies(Array.isArray(data) ? data : data.movies || []);
      } catch {
        setMovies([]);
      } finally {
        setLoading(false);
      }
    }
    fetchMovies();
  }, []);

  if (loading) {
    return <LoadingSpinner />;
  }

  return (
    <>
      <h1 className="mb-4">Now Showing</h1>
      <Row className="g-4">
        {movies.map((movie) => (
          <Col key={movie.id || movie._id} md={6} lg={4}>
            <MovieCard movie={movie} />
          </Col>
        ))}
      </Row>
      {!movies.length && <p className="text-muted mt-4">No movies found.</p>}
    </>
  );
}

export default HomePage;
