import React, { useEffect, useState } from "react";
import { Button, Card, Col, Row } from "react-bootstrap";
import { Link, useParams } from "react-router-dom";
import axiosInstance from "../api/axios";
import LoadingSpinner from "../components/LoadingSpinner";

function MovieDetailPage() {
  const { movieId } = useParams();
  const [movie, setMovie] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchMovie() {
      try {
        const { data } = await axiosInstance.get(`/movies/${movieId}`);
        setMovie(data.movie || data);
      } catch {
        setMovie(null);
      } finally {
        setLoading(false);
      }
    }
    fetchMovie();
  }, [movieId]);

  if (loading) {
    return <LoadingSpinner />;
  }

  if (!movie) {
    return <p>Movie details not available.</p>;
  }

  return (
    <Row>
      <Col md={5}>
        <img
          className="img-fluid rounded"
          src={movie.posterUrl || "https://via.placeholder.com/500x280?text=Movie+Poster"}
          alt={movie.title}
        />
      </Col>
      <Col md={7}>
        <Card>
          <Card.Body>
            <Card.Title as="h2">{movie.title}</Card.Title>
            <Card.Text>{movie.description || "No description available."}</Card.Text>
            <Card.Text>
              <strong>Duration:</strong> {movie.duration || "N/A"}
            </Card.Text>
            <Card.Text>
              <strong>Genre:</strong> {movie.genre || "N/A"}
            </Card.Text>
            <Button as={Link} to={`/seat-selection/${movie.defaultShowId || movieId}`}>
              Book Now
            </Button>
          </Card.Body>
        </Card>
      </Col>
    </Row>
  );
}

export default MovieDetailPage;
