import React, { useState } from "react";
import { Button, Card, Form } from "react-bootstrap";
import { useLocation, useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import axiosInstance from "../api/axios";
import { formatCurrency } from "../utils/helpers";

function PaymentPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const [submitting, setSubmitting] = useState(false);
  const bookingData = location.state;

  if (!bookingData?.selectedSeats?.length) {
    return <p>Invalid booking session. Please select seats again.</p>;
  }

  const handlePayment = async (event) => {
    event.preventDefault();
    setSubmitting(true);
    try {
      const payload = {
        showId: bookingData.showId,
        seats: bookingData.selectedSeats,
        amount: bookingData.amount
      };
      const { data } = await axiosInstance.post("/bookings", payload);
      toast.success("Payment successful");
      navigate("/booking-confirmation", {
        state: {
          bookingId: data.bookingId || data.id || "TEMP-BOOKING-ID",
          ...payload
        }
      });
    } catch (error) {
      toast.error(error.response?.data?.message || "Payment failed");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Card>
      <Card.Body>
        <h2 className="mb-3">Payment</h2>
        <p>
          Amount Payable: <strong>{formatCurrency(bookingData.amount)}</strong>
        </p>
        <Form onSubmit={handlePayment}>
          <Form.Group className="mb-3" controlId="cardName">
            <Form.Label>Name on Card</Form.Label>
            <Form.Control required />
          </Form.Group>
          <Form.Group className="mb-3" controlId="cardNumber">
            <Form.Label>Card Number</Form.Label>
            <Form.Control required maxLength={16} />
          </Form.Group>
          <Button type="submit" disabled={submitting}>
            {submitting ? "Processing..." : "Pay Now"}
          </Button>
        </Form>
      </Card.Body>
    </Card>
  );
}

export default PaymentPage;
