import React, { useEffect, useState } from "react";
import { Card, Table } from "react-bootstrap";
import axiosInstance from "../api/axios";
import LoadingSpinner from "../components/LoadingSpinner";
import { formatCurrency, formatDate } from "../utils/helpers";

function BookingHistoryPage() {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchBookings() {
      try {
        const { data } = await axiosInstance.get("/bookings/my");
        setBookings(Array.isArray(data) ? data : data.bookings || []);
      } catch {
        setBookings([]);
      } finally {
        setLoading(false);
      }
    }
    fetchBookings();
  }, []);

  if (loading) {
    return <LoadingSpinner />;
  }

  return (
    <Card>
      <Card.Body>
        <h2 className="mb-3">Booking History</h2>
        <Table responsive striped>
          <thead>
            <tr>
              <th>Booking ID</th>
              <th>Seats</th>
              <th>Amount</th>
              <th>Date</th>
            </tr>
          </thead>
          <tbody>
            {bookings.map((booking) => (
              <tr key={booking.id || booking._id}>
                <td>{booking.id || booking._id}</td>
                <td>{booking.seats?.join(", ") || "N/A"}</td>
                <td>{formatCurrency(booking.amount || 0)}</td>
                <td>{formatDate(booking.createdAt)}</td>
              </tr>
            ))}
          </tbody>
        </Table>
        {!bookings.length && <p className="text-muted mb-0">No bookings yet.</p>}
      </Card.Body>
    </Card>
  );
}

export default BookingHistoryPage;
